ax.plot(
    time_ms,
    xdp50_segment,
    label="XDP 50%",
    color="blue",
    linewidth=2
)

ax.plot(
    time_ms,
    user50_segment,
    label="User 50%",
    color="orange",
    linewidth=2
)

ax.set_xlabel("Time (ms)", fontsize=12)
ax.set_ylabel("CPU (%)", fontsize=12)

ax.set_xlim(0, 10000)
ax.set_xticks(np.arange(0, 10001, 1000))

# 可依你的資料範圍調整
ax.set_ylim(bottom=0)

ax.grid(
    True,
    linestyle="--",
    alpha=0.4
)

ax.legend()
plt.tight_layout()
plt.show()